const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),$=s=>document.querySelector(s),keys=new Set(),pressed=new Set();
const platforms=[{x:265,y:480,w:670,h:24},{x:315,y:335,w:190,h:12},{x:695,y:335,w:190,h:12},{x:520,y:225,w:160,h:12}];
let fighters=[],particles=[],state='ready',time=180,last=0,acc=0,shake=0,tick=0,audio=null,sound=false;
function fighter(i){return {i,x:i?755:445,y:410,vx:0,vy:0,dir:i?-1:1,dmg:0,lives:3,jumps:0,ground:false,stun:0,cool:0,attack:0,heavy:false,hit:false,inv:0,shield:100,blocking:false,ai:0};}
function tone(f=440,d=.08){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d);}catch{}}
function burst(x,y,color,n=20){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=2+Math.random()*8;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:30+Math.random()*20,color});}}
function start(){fighters=[fighter(0),fighter(1)];particles=[];time=180;state='playing';keys.clear();pressed.clear();$('#overlay').hidden=true;$('#pause').textContent='暂停';$('#mode').disabled=true;canvas.focus();hud();tone(640);}
function show(title,text,button){$('#overlay').hidden=false;$('#overlay h1').textContent=title;$('#overlay .eyebrow').textContent=state==='paused'?'中场休息':'对战结果';$('#overlay p').textContent=text;$('#start').innerHTML=button;}
function pause(){if(state==='playing'){state='paused';show('暂停一下。','调整好节奏，继续下一次击飞。','继续对战');$('#pause').textContent='继续';}else if(state==='paused'){state='playing';$('#overlay').hidden=true;$('#pause').textContent='暂停';canvas.focus();}keys.clear();pressed.clear();}
function finish(winner){state='over';$('#mode').disabled=false;show(winner===-1?'势均力敌！':winner===0?'脉冲赢得对战！':'焰核赢得对战！',winner===-1?'双方生命和伤害相同，再来一局决胜。':'下一场，试试空中追击和舞台边缘重击。','再来一局 <span>ENTER</span>');tone(winner===0?880:180,.3);}
function hud(){fighters.forEach((p,i)=>{$('#d'+i).innerHTML=Math.round(p.dmg)+'<span>%</span>';$('#s'+i).textContent='● '.repeat(Math.max(0,p.lives));});$('#timer').textContent=Math.floor(time/60).toString().padStart(2,'0')+':'+Math.ceil(time%60).toString().padStart(2,'0');}
function jump(p){if(p.jumps<2&&p.stun<=0){p.vy=-11.6;p.jumps++;p.ground=false;burst(p.x,p.y+26,p.i?'#ff6a8c':'#56e4ff',8);tone(420+p.jumps*100);}}
function attack(p,heavy){if(p.cool>0||p.stun>0||p.blocking)return;p.heavy=heavy;p.attack=heavy?30:18;p.cool=heavy?55:26;p.hit=false;tone(heavy?150:300);}
function cpu(p,o){let move=0,j=false,a=false,h=false,b=false;const dx=o.x-p.x,dy=o.y-p.y;p.ai++;if(p.stun<=0){move=Math.abs(dx)>57?Math.sign(dx):0;if(p.x<285)move=1;if(p.x>915)move=-1;if((p.y>450&&(p.x<275||p.x>925))||(dy<-55&&p.ground))j=true;if(!p.ground&&p.y>460&&p.vy>0&&p.jumps<2)j=true;if(Math.abs(dx)<105&&Math.abs(dy)<60&&p.ai%11===0){a=true;h=o.dmg>65||p.ai%33===0;}b=o.attack>0&&Math.abs(dx)<115&&p.ai%80<30;}return {move,j,a,h,b};}
function controls(p){if(p.i&&$('#mode').value==='cpu')return cpu(p,fighters[0]);const k=p.i?['arrowleft','arrowright','arrowup','1','2','3']:['a','d','w','j','k','l'];return {move:Number(keys.has(k[1]))-Number(keys.has(k[0])),j:pressed.has(k[2]),a:(p.i ? pressed.has(k[3]) : pressed.has('mouseattack'))||pressed.has(k[4]),h:pressed.has(k[4]),b:keys.has(k[5])};}
function update(){tick++;if(state!=='playing'){pressed.clear();return;}time=Math.max(0,time-1/60);for(const p of fighters){const c=controls(p);p.cool=Math.max(0,p.cool-1);p.attack=Math.max(0,p.attack-1);p.inv=Math.max(0,p.inv-1);p.stun=Math.max(0,p.stun-1);p.blocking=c.b&&p.shield>2&&p.stun===0&&p.attack===0;p.shield=Math.max(0,Math.min(100,p.shield+(p.blocking?-.6:.35)));if(p.stun===0){if(c.move){p.dir=c.move;p.vx+=c.move*(p.ground?.9:.45);}if(c.j)jump(p);if(c.a)attack(p,c.h);p.vx*=p.blocking?.65:p.ground?.8:.985;p.vx=Math.max(-6.1,Math.min(6.1,p.vx));}else p.vx*=.99;const old=p.y;p.x+=p.vx;p.vy+=.48;p.vy=Math.min(p.vy,16);p.y+=p.vy;p.ground=false;for(const q of platforms)if(p.vy>=0&&old+27<=q.y+2&&p.y+27>=q.y&&p.x+17>q.x&&p.x-17<q.x+q.w){p.y=q.y-27;p.vy=0;p.ground=true;p.jumps=0;break;}if(p.x<-110||p.x>1310||p.y>790||p.y<-200){burst(Math.max(20,Math.min(1180,p.x)),Math.max(80,Math.min(610,p.y)),p.i?'#ff6a8c':'#56e4ff',55);shake=18;tone(90,.25);p.lives--;if(p.lives<=0){finish(1-p.i);break;}Object.assign(p,{x:p.i?740:460,y:100,vx:0,vy:0,dmg:0,jumps:0,stun:0,inv:150,attack:0});}}
if(state==='playing')for(const p of fighters){const o=fighters[1-p.i],active=p.heavy?p.attack<=19&&p.attack>=10:p.attack<=13&&p.attack>=6;const dx=(o.x-p.x)*p.dir;if(active&&!p.hit&&dx>-14&&dx<(p.heavy?115:83)&&Math.abs(o.y-p.y)<58&&o.inv===0){p.hit=true;if(o.blocking){o.shield=Math.max(0,o.shield-(p.heavy?36:18));burst(o.x,o.y,'#ffffff',10);tone(720);if(o.shield===0)o.stun=65;}else{o.dmg+=p.heavy?19:9;const force=(p.heavy?7:4)+o.dmg*(p.heavy?.12:.055);o.vx=p.dir*force;o.vy=-force*.65-2;o.stun=18+o.dmg*.1;o.inv=16;o.ground=false;shake=p.heavy?10:4;burst(o.x,o.y,p.i?'#ff6a8c':'#56e4ff',24);tone(p.heavy?100:210,.12);}}}
if(state==='playing'&&time===0){const[a,b]=fighters;finish(a.lives!==b.lives?(a.lives>b.lives?0:1):a.dmg===b.dmg?-1:a.dmg<b.dmg?0:1);}particles=particles.filter(p=>{p.x+=p.vx;p.y+=p.vy;p.vy+=.12;return --p.life>0;});shake*=.85;pressed.clear();hud();}
function line(x,y,x2,y2,color,width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x2,y2);ctx.stroke();}
function draw(){ctx.clearRect(0,0,1200,680);const bg=ctx.createLinearGradient(0,0,0,680);bg.addColorStop(0,'#10182e');bg.addColorStop(.65,'#192640');bg.addColorStop(1,'#0b1025');ctx.fillStyle=bg;ctx.fillRect(0,0,1200,680);for(let i=0;i<65;i++){const x=(i*173.7)%1200,y=(i*87.3)%470;ctx.fillStyle=`rgba(179,213,255,${.18+.2*Math.sin(tick*.012+i)})`;ctx.fillRect(x,y,i%6?2:3,2);}ctx.save();ctx.translate(600,285);ctx.scale(1,.32);ctx.strokeStyle='#67b8e51a';ctx.lineWidth=2;for(let r=230;r<510;r+=85){ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.stroke();}ctx.restore();for(let i=0;i<16;i++)line(600,370,(i-3)*150,680,'#4582ad12');for(let i=0;i<8;i++)line(0,420+i*i*5,1200,420+i*i*5,'#4582ad12');ctx.save();if(shake>1)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);for(const q of platforms){ctx.shadowBlur=q.h>12?22:12;ctx.shadowColor='#57d9ff';ctx.fillStyle='#4bd5f4';ctx.fillRect(q.x,q.y,q.w,3);ctx.shadowBlur=0;ctx.fillStyle='#233a56';ctx.fillRect(q.x,q.y+3,q.w,q.h);ctx.fillStyle='#12263d';ctx.beginPath();ctx.moveTo(q.x,q.y+q.h);ctx.lineTo(q.x+q.w,q.y+q.h);ctx.lineTo(q.x+q.w-38,q.y+q.h+32);ctx.lineTo(q.x+38,q.y+q.h+32);ctx.fill();for(let x=q.x+25;x<q.x+q.w;x+=50)line(x,q.y+8,x+18,q.y+8,'#5fe8ff55',2);}
for(const p of fighters.length?fighters:[fighter(0),fighter(1)]){const color=p.i?'#ff6a8c':'#56e4ff';ctx.save();ctx.translate(p.x,p.y);if(p.inv>0&&tick%8<4)ctx.globalAlpha=.4;ctx.shadowColor=color;ctx.shadowBlur=16;ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(-17,-24,34,49,9);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#091626';ctx.fillRect(-12,-12,24,10);ctx.fillStyle='white';ctx.fillRect(p.dir>0?3:-10,-10,7,4);ctx.fillStyle='#edf8ff';ctx.fillRect(-13,15,8,12);ctx.fillRect(5,15,8,12);ctx.fillStyle=color;ctx.fillRect(p.dir>0?14:-25,0,11,15);ctx.fillStyle='#d1ddf5';ctx.font='bold 13px system-ui';ctx.textAlign='center';ctx.fillText(p.i?($('#mode').value==='cpu'?'CPU':'P2'):'P1',0,-40);if(p.blocking){ctx.strokeStyle=color;ctx.lineWidth=3;ctx.globalAlpha=.3+p.shield/200;ctx.beginPath();ctx.arc(0,0,40,0,Math.PI*2);ctx.stroke();}if(p.attack){ctx.globalAlpha=.6;ctx.strokeStyle=p.heavy?'#ffe6a5':color;ctx.lineWidth=p.heavy?10:6;ctx.beginPath();ctx.arc(p.dir*22,-2,p.heavy?67:45,p.dir>0?-.9:2.2,p.dir>0?.9:4.1);ctx.stroke();}ctx.restore();}for(const p of particles){ctx.globalAlpha=Math.min(1,p.life/20);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,4,4);}ctx.globalAlpha=1;ctx.restore();}
function frame(now){if(!last)last=now;acc+=Math.min((now-last)/1000,.05);last=now;while(acc>=1/60){update();acc-=1/60;}draw();requestAnimationFrame(frame);}requestAnimationFrame(frame);
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(e.target.matches('select,button')&&k!=='escape')return;if(['a','d','w','j','k','l','arrowleft','arrowright','arrowup','1','2','3','enter','escape'].includes(k)){e.preventDefault();if(!keys.has(k))pressed.add(k);keys.add(k);if(!e.repeat&&k==='enter'){if(state==='paused')pause();else if(state!=='playing')start();}if(!e.repeat&&k==='escape')pause();}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{if(state==='playing')pause();keys.clear();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pause();});$('#start').onclick=()=>state==='paused'?pause():start();$('#pause').onclick=pause;$('#mode').onchange=()=>{$('#p2label').textContent=$('#mode').value==='cpu'?'02 / 电脑':'02 / 玩家';$('#localhelp').hidden=$('#mode').value!=='local';};$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent='音效：'+(sound?'开':'关');$('#sound').setAttribute('aria-pressed',String(sound));tone();};document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);pressed.add(b.dataset.key);};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>keys.delete(b.dataset.key);});
